// ============================================================
// Parse JotForm & Generate Client Code
// Handles multiple JotForm data formats
// ============================================================

const body = $input.first().json.body || $input.first().json;

// --- STRATEGY 1: rawRequest JSON string ---
let parsed = null;
try {
  if (body.rawRequest && typeof body.rawRequest === 'string') {
    parsed = JSON.parse(body.rawRequest);
  } else if (body.rawRequest && typeof body.rawRequest === 'object') {
    parsed = body.rawRequest;
  }
} catch (e) {
  parsed = null;
}

// --- STRATEGY 2: q-prefixed fields (q1_whatIs, q2_email, etc.) ---
function fromQFields(b) {
  const qMap = {};
  for (const key of Object.keys(b)) {
    if (/^q\d+/.test(key)) {
      qMap[key] = b[key];
    }
  }
  if (Object.keys(qMap).length === 0) return null;

  // Sort by question number
  const sorted = Object.entries(qMap).sort((a, b) => {
    const numA = parseInt(a[0].match(/^q(\d+)/)[1]);
    const numB = parseInt(b[0].match(/^q(\d+)/)[1]);
    return numA - numB;
  });

  // Map by order (best-effort mapping based on form field order)
  const fieldOrder = [
    'client_name', 'client_email', 'whatsapp_number', 'brand_name', 'website_url',
    'product_feature', 'differentiator', 'competitors', 'competitor_strengths',
    'target_user', 'biggest_problem', 'main_hesitation',
    'social_proof', 'selling_proposition', 'brand_personality', 'credibility_point', 'transformation',
    'best_concepts', 'compliance', 'reference_ads', 'available_assets', 'do_not_say', 'additional_notes'
  ];

  const result = {};
  sorted.forEach(([key, val], i) => {
    if (i < fieldOrder.length) {
      result[fieldOrder[i]] = val;
    }
  });
  return result;
}

// --- STRATEGY 3: Direct field names ---
function fromDirectFields(b) {
  const directFields = [
    'client_name', 'client_email', 'whatsapp_number', 'brand_name', 'website_url',
    'product_feature', 'differentiator', 'competitors', 'competitor_strengths',
    'target_user', 'biggest_problem', 'main_hesitation',
    'social_proof', 'selling_proposition', 'brand_personality', 'credibility_point', 'transformation',
    'best_concepts', 'compliance', 'reference_ads', 'available_assets', 'do_not_say', 'additional_notes'
  ];
  const found = {};
  let count = 0;
  for (const f of directFields) {
    if (b[f] !== undefined) {
      found[f] = b[f];
      count++;
    }
  }
  return count > 0 ? found : null;
}

// Resolve data source
let data = parsed || fromQFields(body) || fromDirectFields(body) || body;

// --- HELPER: Clean a field value ---
function clean(val) {
  if (val === undefined || val === null) return '';
  if (Array.isArray(val)) return val.map(v => String(v).trim()).filter(Boolean).join(', ');
  if (typeof val === 'object') {
    // Handle name object: { first, last } or { prefix, first, middle, last }
    if (val.first || val.last) {
      return [val.prefix, val.first, val.middle, val.last].filter(Boolean).map(s => String(s).trim()).join(' ');
    }
    // Handle phone object: { area, phone } or { countryCode, area, phone }
    if (val.phone !== undefined) {
      const parts = [val.countryCode, val.area, val.phone].filter(Boolean).map(s => String(s).replace(/[\s\-()]/g, ''));
      return parts.join('');
    }
    return JSON.stringify(val);
  }
  return String(val).trim();
}

// --- Extract and clean all 23 fields ---
const client_name = clean(data.client_name || data.clientName || data.name);
const client_email = clean(data.client_email || data.clientEmail || data.email);
const whatsapp_number = clean(data.whatsapp_number || data.whatsappNumber || data.whatsapp || data.phone);
const brand_name = clean(data.brand_name || data.brandName || data.brand);
const website_url = clean(data.website_url || data.websiteUrl || data.website);
const product_feature = clean(data.product_feature || data.productFeature);
const differentiator = clean(data.differentiator);
const competitors = clean(data.competitors);
const competitor_strengths = clean(data.competitor_strengths || data.competitorStrengths);
const target_user = clean(data.target_user || data.targetUser);
const biggest_problem = clean(data.biggest_problem || data.biggestProblem);
const main_hesitation = clean(data.main_hesitation || data.mainHesitation);
const social_proof = clean(data.social_proof || data.socialProof);
const selling_proposition = clean(data.selling_proposition || data.sellingProposition);
const brand_personality = clean(data.brand_personality || data.brandPersonality);
const credibility_point = clean(data.credibility_point || data.credibilityPoint);
const transformation = clean(data.transformation);
const best_concepts = clean(data.best_concepts || data.bestConcepts);
const compliance = clean(data.compliance);
const reference_ads = clean(data.reference_ads || data.referenceAds);
const available_assets = clean(data.available_assets || data.availableAssets);
const do_not_say = clean(data.do_not_say || data.doNotSay);
const additional_notes = clean(data.additional_notes || data.additionalNotes);

// --- Generate Client Code ---
// Rules: first 3 chars of brand name (uppercase), skip "The" prefix, strip special chars
function generateClientCode(brandName) {
  let name = brandName.trim();
  // Remove leading "The " (case-insensitive)
  name = name.replace(/^the\s+/i, '');
  // Remove special characters, keep letters and spaces
  name = name.replace(/[^a-zA-Z\s]/g, '');
  // Take first 3 alphabetic characters of concatenated name (no spaces)
  // Examples: 'Yaan Man' → YAA, 'Supafuelz' → SUP, 'The Pain Company' → (skip The) → PAI
  const concat = name.replace(/\s+/g, '');
  const code = (concat.substring(0, 3) || 'XXX').toUpperCase();

  // Add date: MMDD
  const now = new Date();
  const mm = String(now.getMonth() + 1).padStart(2, '0');
  const dd = String(now.getDate()).padStart(2, '0');
  return `${code}-${mm}${dd}`;
}

const client_code = generateClientCode(brand_name);

// Start date: today in DD/MM/YYYY
const now = new Date();
const start_date = `${String(now.getDate()).padStart(2, '0')}/${String(now.getMonth() + 1).padStart(2, '0')}/${now.getFullYear()}`;

return [{
  json: {
    client_code,
    brand_name,
    client_name,
    client_email,
    whatsapp_number,
    website_url,
    product_feature,
    differentiator,
    competitors,
    competitor_strengths,
    target_user,
    biggest_problem,
    main_hesitation,
    social_proof,
    selling_proposition,
    brand_personality,
    credibility_point,
    transformation,
    best_concepts,
    compliance,
    reference_ads,
    available_assets,
    do_not_say,
    additional_notes,
    status: 'Onboarding',
    start_date,
    folder_name: `${brand_name} - UGC`,
    list_name: `${brand_name} - UGC Pipeline`,
    channel_name: `${brand_name} - UGC`
  }
}];

// ============================================================
// Generate 10 Onboarding Tasks for ClickUp
// ============================================================

const d = $('Parse JotForm & Generate Client Code').first().json;
const listId = $('Create Pipeline List in Folder').first().json.id;

function dueDate(daysFromNow) {
  const dt = new Date();
  dt.setDate(dt.getDate() + daysFromNow);
  dt.setHours(18, 0, 0, 0); // 6 PM deadline
  return dt.getTime();
}

const tasks = [
  {
    name: 'Review onboarding brief & flag gaps',
    due_date: dueDate(1),
    priority: 1,
    description: `Read ${d.brand_name} brief. Flag items marked 'discuss on call' or blank.\n\nProduct: ${d.product_feature}\nDifferentiator: ${d.differentiator}\nCompliance: ${d.compliance || 'None specified'}\nDo NOT say: ${d.do_not_say || 'None specified'}`,
    listId
  },
  {
    name: 'Schedule kickoff call with client',
    due_date: dueDate(1),
    priority: 1,
    description: `Contact ${d.client_name} via WhatsApp (${d.whatsapp_number}) or email (${d.client_email}).\nSchedule call to discuss flagged items + creative direction.`,
    listId
  },
  {
    name: 'Competitor ad research & analysis',
    due_date: dueDate(3),
    priority: 2,
    description: `Research: ${d.competitors}\nWhat they do better: ${d.competitor_strengths}\nPull current ads from Meta Ad Library.\nReference ads client likes: ${d.reference_ads || 'None provided'}`,
    listId
  },
  {
    name: 'Define creative angles & concepts',
    due_date: dueDate(3),
    priority: 2,
    description: `Based on brief:\nDifferentiator: ${d.differentiator}\nTarget: ${d.target_user}\nProblem solved: ${d.biggest_problem}\nHesitation: ${d.main_hesitation}\nBrand personality: ${d.brand_personality}\nRef ads: ${d.reference_ads || 'None'}\n\nPropose 3-5 creative angles.`,
    listId
  },
  {
    name: 'Write first batch of UGC scripts',
    due_date: dueDate(5),
    priority: 2,
    description: `Write 3-5 UGC scripts for ${d.product_feature}\nSelling proposition: ${d.selling_proposition}\nTransformation: ${d.transformation}\nBest concepts: ${d.best_concepts || 'None specified'}\n\n⚠️ COMPLIANCE: ${d.compliance || 'None'}\n🚫 DO NOT: ${d.do_not_say || 'None'}`,
    listId
  },
  {
    name: 'Source & match UGC creators',
    due_date: dueDate(5),
    priority: 3,
    description: `Find creators matching:\nBrand personality: ${d.brand_personality}\nTarget audience: ${d.target_user}\nContent style and tone requirements`,
    listId
  },
  {
    name: 'Internal creative review',
    due_date: dueDate(7),
    priority: 3,
    description: `Review scripts before sharing with ${d.client_name}.\nCheck against: ${d.compliance || 'No compliance notes'}\nEnsure nothing in do-not list: ${d.do_not_say || 'None'}`,
    listId
  },
  {
    name: 'Client script approval',
    due_date: dueDate(8),
    priority: 2,
    description: `Share scripts with ${d.client_name} (${d.client_email} / WhatsApp ${d.whatsapp_number}) for feedback.`,
    listId
  },
  {
    name: 'UGC shoot coordination',
    due_date: dueDate(12),
    priority: 3,
    description: `Brief creators, coordinate shoots.\nAvailable client assets: ${d.available_assets || 'None specified'}`,
    listId
  },
  {
    name: 'First draft delivery to client',
    due_date: dueDate(15),
    priority: 1,
    description: `Deliver first round of edited UGC videos to ${d.client_name} for review.`,
    listId
  }
];

return tasks.map(t => ({ json: t }));

